struct LoginState { email: String, busy: bool }

impl LoginState {
    fn submit_enabled(&self) -> bool { !self.email.is_empty() && !self.busy } // decision
    fn submit(&mut self) { self.busy = true; /* command */ }
}

// egui frame function:
ui.text_edit_singleline(&mut state.email);
if ui.add_enabled(state.submit_enabled(), egui::Button::new("Log in")).clicked() {
    state.submit();
}
